<?php
namespace App\Http\Controllers\Admin;use App\Models\Lead;use Illuminate\Http\Request;
class LeadController extends CrudController { protected string $model=Lead::class;protected array $rules=['name'=>'required|string|max:190','phone'=>'nullable|string|max:60','email'=>'nullable|email|max:190','source'=>'nullable|string|max:80','interest'=>'nullable|string|max:190','vehicle_id'=>'nullable|exists:vehicles,id','location_id'=>'nullable|exists:locations,id','message'=>'nullable|string|max:5000','status'=>'nullable|in:New,Contacted,Qualified,Converted,Lost','admin_notes'=>'nullable|string|max:5000'];protected array $defaults=['source'=>'Website','status'=>'New']; public function index(Request $r){return response()->json(Lead::with(['vehicle','location'])->when($r->status,fn($q,$v)=>$q->where('status',$v))->when($r->search,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like',"%$v%")->orWhere('phone','like',"%$v%")->orWhere('email','like',"%$v%")))->latest()->paginate(100));} }
